const b = items[0].json.body;
const prompt = `You are a Patient Registration Agent in an Emergency Department.
Patient: ${b.name}, Age ${b.age}${b.sex}, arrived by ${b.arrivalMode}.
Chief Complaint: ${b.chiefComplaint}
PMHx: ${b.pmhx} | Meds: ${b.meds} | Allergies: ${b.allergies}
Respond in JSON only (no markdown fences):
{"summary":"one sentence overview","demographics":"formatted string","complaint":"clinical language"}`;
const groqBody = JSON.stringify({ model: 'llama-3.1-8b-instant', messages: [{ role: 'user', content: prompt }], temperature: 0.3 });
return [{ json: { _input: b, groqBody } }];

const raw = items[0].json.choices[0].message.content.trim()
  .replace(/^```json\s*/i,'').replace(/^```\s*/i,'').replace(/\s*```$/i,'').trim();
const patientAgent = JSON.parse(raw);
const _input = $('Build Patient Payload').first().json._input;
return [{ json: { _input, patientAgent } }];

const { _input, patientAgent } = items[0].json;
const prompt = `You are an ED Triage Nurse using the Australian Triage Scale.
Patient: ${patientAgent.summary}
Complaint: ${patientAgent.complaint}
Vitals: HR ${_input.hr}, RR ${_input.rr}, BP ${_input.sbp}/${_input.dbp}, Temp ${_input.temp}C, SpO2 ${_input.spo2}%
PMHx: ${_input.pmhx}
ATS: 1=Resuscitation 2=Emergency 3=Urgent 4=Semi-urgent 5=Non-urgent
Respond in JSON only (no markdown fences):
{"category":2,"categoryName":"Emergency","reasoning":"2 sentences","keySymptoms":["s1","s2"]}`;
const groqBody = JSON.stringify({ model: 'llama-3.3-70b-versatile', messages: [{ role: 'user', content: prompt }], temperature: 0.3 });
return [{ json: { _input, patientAgent, groqBody } }];

