const { _input, patientAgent, triageAgent } = items[0].json;
const prompt = `You are a Triage Nurse recording vitals and orders.
Patient: ${patientAgent.summary}
Triage: CAT ${triageAgent.category} — ${triageAgent.categoryName}
Vitals: HR ${_input.hr}, RR ${_input.rr}, BP ${_input.sbp}/${_input.dbp}, Temp ${_input.temp}C, SpO2 ${_input.spo2}%
Flag abnormal vitals (HR>100/<60, RR>20/<12, SBP>160/<100, Temp>38/<36, SpO2<95).
Respond in JSON only (no markdown fences):
{"vitalsAssessment":"1-2 sentences","abnormalFlags":["flag1"],"ordersPlaced":["order1"],"labsOrdered":["lab1"]}`;
const groqBody = JSON.stringify({ model: 'llama-3.3-70b-versatile', messages: [{ role: 'user', content: prompt }], temperature: 0.3 });
return [{ json: { _input, patientAgent, triageAgent, groqBody } }];

