const { _input, patientAgent, triageAgent, nurseAgent } = items[0].json;
const flags = (nurseAgent.abnormalFlags||[]).join(', ')||'none';
const labs = (nurseAgent.labsOrdered||[]).join(', ')||'none';
const prompt = `You are an ED Doctor.
Patient: ${patientAgent.summary}
Triage: CAT ${triageAgent.category} — ${triageAgent.reasoning}
Nursing: ${nurseAgent.vitalsAssessment}
Abnormal flags: ${flags}
Labs ordered: ${labs}
Complaint: ${patientAgent.complaint} | PMHx: ${_input.pmhx} | Meds: ${_input.meds} | Allergies: ${_input.allergies}
Respond in JSON only (no markdown fences):
{"clinicalPicture":"2-3 sentences","differentialDiagnosis":["primary","2nd","3rd"],"reasoning":"2 sentences"}`;
const groqBody = JSON.stringify({ model: 'llama-3.3-70b-versatile', messages: [{ role: 'user', content: prompt }], temperature: 0.3 });
return [{ json: { _input, patientAgent, triageAgent, nurseAgent, groqBody } }];

