const { _input, patientAgent, triageAgent, nurseAgent, doctorAgent } = items[0].json;
const flags = (nurseAgent.abnormalFlags||[]).join(', ')||'none';
const primary = (doctorAgent.differentialDiagnosis||[])[0]||'unknown';
const prompt = `You are an ED Decision Agent.
Patient: ${patientAgent.summary}
Triage: CAT ${triageAgent.category} — ${triageAgent.categoryName}
Clinical: ${doctorAgent.clinicalPicture}
Primary Dx: ${primary}
Abnormal flags: ${flags}
Disposition options: Admit to Hospital | Short Stay Unit | Discharge Home
Respond in JSON only (no markdown fences):
{"disposition":"Admit to Hospital","confidence":0.85,"probabilities":{"admit":0.7,"shortStay":0.2,"discharge":0.1},"rationale":"2-3 sentences"}`;
const groqBody = JSON.stringify({ model: 'llama-3.3-70b-versatile', messages: [{ role: 'user', content: prompt }], temperature: 0.3 });
return [{ json: { _input, patientAgent, triageAgent, nurseAgent, doctorAgent, groqBody } }];

